package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Window;import org.brightstats.stats.*;import org.brightstats.data.*;
final class LatentLikelihoodDialog {
 record Settings(LatentInteractionSem.Model model,LatentInteractionSem.Options options,List<String> sourceNames,boolean compareLinear){Settings{Objects.requireNonNull(model);Objects.requireNonNull(options);sourceNames=List.copyOf(sourceNames);if(compareLinear&&model.interactions().isEmpty())throw new IllegalArgumentException("Add a product term or disable the interaction-free comparison.");for(var factor:model.predictors())for(int column:factor.columns())if(column>=sourceNames.size())throw new IllegalArgumentException("Predictor indicator binding is missing.");for(int column:model.outcome().columns())if(column>=sourceNames.size())throw new IllegalArgumentException("Outcome indicator binding is missing.");}void validateNames(List<String> names){if(names.size()<sourceNames.size()||!names.subList(0,sourceNames.size()).equals(sourceNames))throw new IllegalArgumentException("Likelihood source columns changed; reconfigure its measurement bindings.");for(var factor:model.predictors())for(int column:factor.columns())if(column>=sourceNames.size())throw new IllegalArgumentException("Predictor indicator binding is missing.");for(int column:model.outcome().columns())if(column>=sourceNames.size())throw new IllegalArgumentException("Outcome indicator binding is missing.");}}
 private final Dialog<Settings> dialog=new Dialog<>();private final TextArea model=new TextArea(),options=new TextArea();private final CheckBox compare=new CheckBox("Fit and compare the same-data interaction-free baseline");private final Label error=new Label();private final ComboBox<LatentInteractionSem.PredictorDistribution> distribution=new ComboBox<>();private final TextField degrees=new TextField();private Settings result;private final List<String> names;private final TabPane editors=new TabPane();
 private LatentLikelihoodDialog(Window owner,List<String> names,Settings current){this.names=List.copyOf(names);dialog.initOwner(owner);dialog.setTitle("Latent interaction / quadratic likelihood");dialog.setResizable(true);Gson json=new GsonBuilder().serializeNulls().setPrettyPrinting().create();model.setText(json.toJson(current.model()));model.setPrefRowCount(14);model.setId("latent-likelihood-model");var solverJson=json.toJsonTree(current.options()).getAsJsonObject();solverJson.remove("predictorDistribution");solverJson.remove("predictorDegreesOfFreedom");options.setText(json.toJson(solverJson));distribution.getItems().setAll(LatentInteractionSem.PredictorDistribution.values());distribution.setValue(current.options().predictorDistribution());distribution.setAccessibleText("Latent predictor distribution");degrees.setText(Double.toString(current.options().predictorDegreesOfFreedom()));degrees.setAccessibleText("Fixed predictor Student t degrees of freedom");options.setPrefRowCount(8);options.setId("latent-likelihood-options");compare.setSelected(current.compareLinear());Label note=UiAppearance.label("Marginal latent ML with checked numerical integration. Normal or covariance-scaled Student-t predictors (fixed df >4) are declared in solver options. Student-t mode integrates every predictor using an exact prior-density importance identity. One outcome, 1–4 centered latent predictors, 3–12 disjoint reflective indicators per factor, independent measurement errors and fixed unit markers. Current canvas paths are not copied: this specification defines a single-outcome model with jointly distributed predictors. Column indices below are zero based. This is not the product-indicator method or a claim of native LMS numerical parity. Complete-case input only; no FIML/MAR correction.");note.setWrapText(true);Label bindings=UiAppearance.label(String.join("; ",java.util.stream.IntStream.range(0,names.size()).mapToObj(i->i+" = "+names.get(i)).toList()));bindings.setWrapText(true);var builder=new LatentModelForm(names,current.model());Button applyForm=new Button("Use guided specification");applyForm.setOnAction(event->{try{model.setText(json.toJson(builder.read()));error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});Button readJson=new Button("Load JSON into guided form");readJson.setOnAction(event->{try{builder.set(LatentInteractionInput.model(BoundedJson.parse(model.getText())));error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});Tab guided=new Tab("Guided measurement and terms",new VBox(8,builder,applyForm));Tab advanced=new Tab("Advanced model / solver JSON",new VBox(8,UiAppearance.label("Numeric column bindings"),bindings,model,options,readJson));guided.setClosable(false);advanced.setClosable(false);editors.getTabs().setAll(guided,advanced);VBox content=new VBox(9,note,new HBox(10,new Label("Predictor distribution"),distribution,new Label("Fixed t df (>4)"),degrees),editors,compare,error);content.setPrefWidth(760);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(660);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{if(editors.getSelectionModel().getSelectedIndex()==0)model.setText(json.toJson(builder.read()));var solver=BoundedJson.parse(options.getText()).getAsJsonObject();if(solver.has("predictorDistribution")||solver.has("predictorDegreesOfFreedom"))throw new IllegalArgumentException("Set predictor distribution and t degrees of freedom using the controls above.");solver.addProperty("predictorDistribution",distribution.getValue().name());solver.addProperty("predictorDegreesOfFreedom",Double.parseDouble(degrees.getText().strip()));result=new Settings(LatentInteractionInput.model(BoundedJson.parse(model.getText())),LatentInteractionInput.options(solver),this.names,compare.isSelected());error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});error.setWrapText(true);dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
 static Optional<Settings> show(Window owner,List<String> names,Settings settings){return new LatentLikelihoodDialog(owner,names,settings).dialog.showAndWait();}
 static Settings defaults(List<String> names,List<PlsSem.Block> blocks){if(blocks.size()<2||blocks.size()>5)throw new IllegalArgumentException("Define a dedicated model with 1–4 reflective predictors and one outcome before configuring this likelihood.");for(var block:blocks)if(block.measurementType()!=PlsSem.MeasurementType.REFLECTIVE)throw new IllegalArgumentException("This likelihood requires reflective measurement blocks; formative inputs are not silently converted.");var predictors=blocks.subList(0,blocks.size()-1).stream().map(b->new LatentInteractionSem.Factor(b.name(),b.columns())).toList();var last=blocks.getLast();var outcome=new LatentInteractionSem.Factor(last.name(),last.columns());var terms=List.of(new LatentInteractionSem.Interaction(0,predictors.size()>1?1:0));return new Settings(new LatentInteractionSem.Model(predictors,outcome,terms),LatentInteractionSem.Options.defaults(),names,true);}
 static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=value.getAsJsonObject();List<String> names=new ArrayList<>();for(var name:o.getAsJsonArray("sourceNames"))names.add(name.getAsString());return new Settings(LatentInteractionInput.model(o.get("model")),LatentInteractionInput.options(o.get("options")),names,o.get("compareLinear").getAsBoolean());}
 static Settings smoke(Window owner,List<String> names,Settings current,java.nio.file.Path image)throws Exception{var controls=new LatentLikelihoodDialog(owner,names,current);controls.dialog.show();var guided=(LatentModelForm)((VBox)controls.editors.getTabs().getFirst().getContent()).getChildren().getFirst();if(!new Gson().toJson(guided.read()).equals(new Gson().toJson(current.model())))throw new AssertionError("Guided latent model changed markers, bindings or products");controls.editors.getSelectionModel().select(1);var run=(Button)controls.dialog.getDialogPane().lookupButton(ButtonType.OK);String original=controls.model.getText();var invalid=BoundedJson.parse(original).getAsJsonObject();invalid.add("correlatedErrors",new JsonArray());controls.model.setText(invalid.toString());run.fire();if(!controls.dialog.isShowing()||controls.result!=null||controls.error.getText().isBlank())throw new AssertionError("Unsupported likelihood field ignored");controls.model.setText(original);String settings=controls.options.getText();var bad=BoundedJson.parse(settings).getAsJsonObject();bad.addProperty("checkNodes",bad.get("nodes").getAsInt());controls.options.setText(bad.toString());run.fire();if(!controls.dialog.isShowing()||controls.result!=null)throw new AssertionError("Unrefined quadrature accepted");controls.options.setText(settings);controls.degrees.setText("4");run.fire();if(!controls.dialog.isShowing()||controls.result!=null)throw new AssertionError("Nonfinite Student quadratic moments accepted");controls.degrees.setText(Double.toString(current.options().predictorDegreesOfFreedom()));controls.error.setText("");controls.dialog.getDialogPane().applyCss();controls.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,controls.dialog.getDialogPane(),1);run.fire();if(controls.dialog.getResult()==null)throw new AssertionError("Valid likelihood dialog rejected");return controls.dialog.getResult();}
}
